function fmtR(x){ return (Math.round(x*10)/10)+'px'; }
function borderRadiusCss(tl, tr, br, bl){
  tl=+tl; tr=+tr; br=+br; bl=+bl;
  if([tl,tr,br,bl].some(function(v){return isNaN(v)||v<0;})) return {error:'半径须为非负数字'};
  var all=tl===tr&&tr===br&&br===bl;
  var opp=tl===br&&tr===bl;
  var shorthand;
  if(all) shorthand=fmtR(tl);
  else if(opp) shorthand=fmtR(tl)+' '+fmtR(tr);
  else shorthand=fmtR(tl)+' '+fmtR(tr)+' '+fmtR(br)+' '+fmtR(bl);
  return {css:'border-radius: '+shorthand+';', shorthand:shorthand, tl:tl, tr:tr, br:br, bl:bl};
}
var EXPORTS={borderRadiusCss:borderRadiusCss};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
